/// A very lightweight PRNG state holding a single `u8` seed.
#[derive(Clone, Copy, Debug)]
pub struct RandomState {
    pub seed: u8,
}

impl RandomState {
    /// Create a new RandomState from the given seed.
    /// 
    /// Specification:
    ///   - no preconditions
    ///   - ensures that the returned state's `seed` field equals the input `seed`
    #[requires(true)]
    #[ensures(|rs: RandomState| rs.seed == seed)]
    pub fn new(seed: u8) -> Self {
        RandomState { seed }
    }
}

/// Deterministically produces a pseudo-random f32 in [0.0, 1.0),
/// taking `state.seed % 8` and mapping 0..7 → {0.0, 0.125, …, 0.875}.
///
/// Specification:
///   - no preconditions
///   - ensures the return value `r` satisfies 0.0 <= r < 1.0
///   - ensures `r == (state.seed % 8) as f32 * 0.125`
#[requires(true)]
#[ensures(|r: f32| 0.0 <= r && r < 1.0)]
#[ensures(|r: f32| r == ((state.seed % 8) as f32) * 0.125)]
pub fn random(state: RandomState) -> f32 {
    // We only need the lower 3 bits (seed % 8)
    let idx = state.seed % 8;
    // For verification: idx is in 0..8
    assert!(idx < 8);
    // Each step is 1/8 = 0.125
    let result = (idx as f32) * 0.125;
    // For verification: result ∈ [0.0, 1.0)
    assert!(0.0 <= result && result < 1.0);
    result
}

